class MountainArray {
public:
    int get(int index);
    int length();
};

class Solution {
public:
    int findInMountainArray(int target, MountainArray &mountainArr) {
        int n = mountainArr.length();
        int lo = 1, hi = n - 2;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            int a = mountainArr.get(mid);
            int b = mountainArr.get(mid + 1);
            if (a < b) lo = mid + 1;
            else hi = mid;
        }
        int peak = lo;
        lo = 0; hi = peak;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int v = mountainArr.get(mid);
            if (v == target) return mid;
            if (v < target) lo = mid + 1;
            else hi = mid - 1;
        }
        lo = peak + 1; hi = n - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int v = mountainArr.get(mid);
            if (v == target) return mid;
            if (v < target) hi = mid - 1;
            else lo = mid + 1;
        }
        return -1;
    }
};
